# The shared HTTP status disposition table, first match wins:
# (first status, last status, disposition); anything else is observed.
HTTP_STATUS_DISPOSITIONS = (
    (401, 401, "security"),
    (403, 403, "security"),
    (429, 429, "wait"),
    (400, 499, "fail"),
    (500, 599, "wait"),
)

# The codes a Fleet profile request is refused with (HTTP 409): it never
# succeeds as sent. Every other profile conflict is a wait (HTTP 503).
